INSERT INTO `job_postings` VALUES (110,45,27,'Customer Care Executive','customer-care-executive-mohali','Full-Time',NULL,NULL,'Customer Service Executive','Mohali,',NULL,NULL,'Work from Home','0',18000.00,23000.00,0.00,'Salary',0,NULL,'null','\"[\\\"telecalling\\\",\\\"Customer Service\\\",\\\"customer care\\\",\\\"fresher\\\",\\\"good communication skills\\\",\\\"voice process\\\",\\\"chat process\\\",\\\"email process\\\",\\\"blended process\\\"]\"',0,'No Preference','0',NULL,'\"[]\"',NULL,'\"[\\\"Graduate Not Required\\\",\\\"\\\",\\\"\\\"]\"','<p>Customer Care Executive (General) -</p>\r\n<p>\r\n</p>\r\n<h3>Education and Experience:1</h3>\r\n<ul>\r\n<li>\r\n<p>We are an equal opportunity employer and value diversity at our company. We do not discriminate on the basis of race, religion, color, national origin, gender, sexual orientation, age, marital status, veteran status, or disability status. We welcome applications from all qualified individuals and encourage those from diverse backgrounds to apply.</p>\r\n</li>\r\n<li>\r\n<p>\r\n</p>\r\n</li>\r\n</ul>\r\n<p>salary-upto23000/month</p>\r\n<p>job timing-Rotational Shift</p>\r\n<p>job location-Mohali</p>\r\n<p>\r\n</p>',NULL,NULL,7,20,'Intermediate','No Preference','\"[\\\"Health Insurance\\\",\\\"Provident Fund\\\"]\"','null',NULL,'nwcchd14@gmail.com','7814151135',0,0,'2025-09-06 07:07:11','2025-09-06 07:07:11',1),(111,46,28,'Copywriter','copywriter-ambala-babyal-village-ambala-hr','Full-Time',NULL,NULL,'Junior Copywriter','Ambala, Babyal village, Ambala, HR',NULL,NULL,'Work from Home','0',20000.00,40000.00,0.00,'Salary',0,NULL,'null','\"[\\\"CSS\\\",\\\"Python\\\"]\"',0,'Whatsapp','0',NULL,'\"[]\"',NULL,'\"[\\\"Graduate Not Required\\\",\\\"\\\",\\\"\\\"]\"','Copywriter \r\n\r\nQualifications:\r\n1. Advanced proficiency in English, both written and spoken.\r\n2. Proven experience as a Copywriter or Content Writer.\r\n3. Portfolio showcasing a range of written work, including website copy, social media content, and marketing materials.\r\n4. Strong understanding of SEO principles and ability to optimize content for search engines.\r\n5. Excellent organizational and time management skills.\r\n6. Ability to work independently and meet deadlines.\r\n7. Strong communication and collaboration skills.\r\nApplication Process:\r\n1. Submit your resume and cover letter explaining your relevant experience and why you would be a good fit for Skymore.\r\n2. Provide a link to your portfolio showcasing your written work.\r\n3. Successful candidates will be invited for an online interview.\r\nSkymore is an equal opportunity employer. We celebrate diversity and are committed to creating an inclusive environment for all employees.\r\nJoin us and help shape the future of Skymore!\r\n\r\nEducation and Experience:\r\nWe are an equal opportunity employer and value diversity at our company. We do not discriminate on the basis of race, religion, color, national origin, gender, sexual orientation, age, marital status, veteran status, or disability status. We welcome applications from all qualified individuals and encourage those from diverse backgrounds to apply.',NULL,NULL,7,1,'Advanced','No Preference','\"[\\\"Provident Fund\\\",\\\"Health Insurance\\\"]\"','null',NULL,'manshu.developer@gmaiil.com','7988532993',0,0,'2025-09-10 04:11:04','2025-09-13 04:36:25',1);
